&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;div style=&quot;float: right; padding: 0 0 8px 8px&quot;&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Ne_vous_arr&#234;tez_pas_au_nom_0&quot;&gt;Ne vous arr&#234;tez pas au nom&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Cadeaux_des_PNJ_1&quot;&gt;Cadeaux des PNJ&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_PNJ_2&quot;&gt;Liste des PNJ&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Associations_de_PNJ_3&quot;&gt; Associations de PNJ &lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Guide du ma&#238;tre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Gamemastery Guide/Guide du ma&#238;tre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoGDM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Pour chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagejoueur.html&quot; title=&quot;PJ&quot;&gt;PJ&lt;/a&gt; qui part &#224; l’aventure dans un monde fantastique, il existe des dizaines ou des centaines de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; dont la fonction est d’offrir des services indispensables aux personnages, de contribuer &#224; des parties importantes de l’histoire ou tout simplement d’agr&#233;menter les pauses entre les aventures. Du &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Villageois.html#FERMIER&quot; title=&quot;PNJ - Les villageois&quot;&gt;fermier&lt;/a&gt; d’un petit bourg jusqu’au &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Amuseurs-Publiques.html#CONTEUR&quot; title=&quot;PNJ - Les amuseurs publics&quot;&gt;conteur d’histoires&lt;/a&gt; de la taverne, du &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Royaut&#233;s.html#ROI&quot; title=&quot;PNJ - Les royaut&#233;s&quot;&gt;roi&lt;/a&gt; le plus puissant jusqu’au plus pauvre des &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Rues.html#MENDIANT&quot; title=&quot;PNJ - Les rues&quot;&gt;gamins des rues&lt;/a&gt;, ces personnages sont les habitants des mondes et des histoires que tous les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; construisent. Ce sont des alli&#233;s ou des adversaires, des employeurs ou des victimes, des foules en liesse ou des meutes m&#233;contentes. Chaque fois que les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagejoueur.html&quot; title=&quot;PJ&quot;&gt;PJ&lt;/a&gt; ont besoin d’aide, veulent commercer ou s’aventurer hors des sentiers battus, ces personnages sont pr&#234;ts &#224; prendre vie.&lt;br /&gt;&lt;br /&gt;Malgr&#233; l’importance des seigneurs qui dirigent le pays, des commer&#231;ants et des pauvres gens constamment en danger, la plupart des aventures se basent sur la menace de monstres qui se terrent loin des rues les plus peupl&#233;es. Ainsi, quand quelque chose tourne mal &#224; la taverne du coin (ce qui se produit t&#244;t ou tard), quand la diplomatie ne suffit plus &#224; la cour royale, ou quand un autre &#233;v&#233;nement inattendu se produit, la plupart des &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; se retrouvent &#224; faire semblant de lancer les d&#233;s ou &#224; tourner les pages &#224; la recherche de profils correspondant &#224; leurs besoins du moment. Le but de ce chapitre est d’aider les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; lors de telles occasions, quand ils ont besoin de caract&#233;ristiques ou d’une rencontre suppl&#233;mentaire qu’ils n’ont pas pr&#233;par&#233;es, ou quand les joueurs tournent &#224; gauche alors qu’il &#233;tait pr&#233;vu qu’ils aillent &#224; droite.&lt;br /&gt;&lt;br /&gt;Les pages qui suivent pr&#233;sentent plus de 80 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; typiques du jeu de r&#244;le Pathfinder. La plupart de ceux-ci ne sont pas con&#231;us pour servir d’adversaires lors de combats contre des aventuriers exp&#233;riment&#233;s mais plut&#244;t pour pr&#233;senter des caract&#233;ristiques g&#233;n&#233;riques qui serviront lors de nombreuses situations moins agit&#233;es. Si le MJ veut conna&#238;tre le bonus d’Estimation d’un commer&#231;ant moyen ou quantifier les talents de navigateur d’un matelot, ces profils fournissent un point de d&#233;part pour une grande vari&#233;t&#233; de personnages rencontr&#233;s quotidiennement. Cela ne veut pas dire pour autant que ces personnages ne permettent pas de construire des rencontres plus dangereuses : si un groupe de &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Ar&#232;nes.html#GLADIATEUR&quot; title=&quot;PNJ - Les ar&#232;nes&quot;&gt;gladiateurs&lt;/a&gt; habitu&#233;s &#224; combattre des monstres ou une troupe de &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Arm&#233;es.html#SOLDATDINFANTERIE&quot; title=&quot;PNJ - Les arm&#233;es&quot;&gt;soldats&lt;/a&gt; peut repr&#233;senter une menace mortelle, c’est &#233;galement le cas d’une foule de &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Villageois.html#FERMIER&quot; title=&quot;PNJ - Les villageois&quot;&gt;fermiers&lt;/a&gt; et d’artisans arm&#233;s de torches. Plusieurs de ces &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; peuvent &#233;galement remplir des r&#244;les beaucoup plus importants dans une campagne : rien n’emp&#234;che un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; de faire d’un dangereux &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Mercenaires.html#CHASSEURDEPRIMES&quot; title=&quot;PNJ - Les mercenaires&quot;&gt;chasseur de primes&lt;/a&gt; ou d’un c&#233;l&#232;bre &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Maraudeurs.html#CAPITAINEPIRATE&quot; title=&quot;PNJ - Les maraudeurs&quot;&gt;capitaine pirate&lt;/a&gt; l’ennemi principal d’une s&#233;rie d’aventures. Ce chapitre peut &#233;galement servir de liste de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; disponibles lorsque les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagejoueur.html&quot; title=&quot;PJ&quot;&gt;PJ&lt;/a&gt; d&#233;sirent engager des hommes de main, des compagnons ou m&#234;me des &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagejoueur.html&quot; title=&quot;PJ&quot;&gt;PJ&lt;/a&gt; temporaires s’ils se retrouvent dans une situation d&#233;licate. En fin de comptes, ces personnages fournissent aux &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; de nouveaux outils et de nouvelles options, leur &#233;vitent d’avoir &#224; interrompre le jeu pour construire un profil juste pour une situation donn&#233;e et leur permettent de d&#233;vouer leur temps et leur cr&#233;ativit&#233; aux parties les plus int&#233;ressantes du jeu : leurs propres aventures.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Ne vous arr&#234;tez pas au nom&lt;a class=&quot;headeranchor&quot; id=&quot;Ne_vous_arr&#234;tez_pas_au_nom_0&quot; href=&quot;#Ne_vous_arr&#234;tez_pas_au_nom_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Ce chapitre pr&#233;sente des profils pour toutes sortes de voyageurs et de commer&#231;ants, de gardes et de pochards, de princesses et de hauts pr&#234;tres et pour des dizaines d’autres habitants des mondes fantastiques. Cependant, on n’y trouve pas de personnages tels que les explorateurs, les alpinistes, les amiraux commandant une armada, les chevaucheurs de dragons ou d’innombrables autres &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; que les aventuriers pourraient croiser. Il y a deux raisons &#224; cela. Tout d’abord, aucune liste de personnages ne peut contenir toutes les cr&#233;ations issues de l’imagination de tous les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt;, donc seul un &#233;chantillon des personnages le plus souvent rencontr&#233;s dans les aventures du jeu de r&#244;le Pathfinder appara&#238;t ici. Ensuite, m&#234;me si un profil a pour titre &#171; guide &#187;, il n’y a aucune raison pour qu’un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; ne puisse pas l’utiliser pour en faire un explorateur, un &#233;claireur, un cowboy ou n’importe quel autre personnage similaire dont il aurait besoin.&lt;br /&gt;&lt;br /&gt;Chaque profil est accompagn&#233; d’un texte d&#233;crivant les individus qu’il repr&#233;sente, expliquant comment il peut &#234;tre utilis&#233; (en l’&#233;tat ou une fois modifi&#233; pour obtenir d’autres personnages) et sugg&#233;rant m&#234;me quels autres &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; pourraient l’accompagner (le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; de ces groupes est pr&#233;cis&#233;). On indique aussi l’&#233;quipement typique que poss&#232;dent les individus de la profession d&#233;crite (celui-ci est calcul&#233; d’apr&#232;s la valeur en pi&#232;ces d’or associ&#233;e au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; du personnage). Souvent, les descriptions contiennent des suggestions pour des variantes d’&#233;quipement ou de dons afin de faciliter l’adaptation du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; &#224; divers r&#244;les et &#224; diverses campagnes. Ces &#233;l&#233;ments, comme tous les autres aspects de ces personnages, peuvent &#234;tre ajust&#233;s au gr&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;Les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; sont group&#233;s par familles de personnages similaires, pour une organisation plus claire et pour permettre aux &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; cherchant un type particulier d’individus de disposer de plusieurs variantes &#224; port&#233;e de main (si un &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Criminels.html#PICKPOCKET&quot; title=&quot;PNJ - Les criminels&quot;&gt;pickpocket&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; &#189; ne convient pas &#224; une rencontre, un &lt;a class=&quot;pagelink&quot; href=&quot;Pnj-Criminels.html#CAMBRIOLEUR&quot; title=&quot;PNJ - Les criminels&quot;&gt;cambrioleur&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; 2 pourrait faire l’affaire). Cela facilite &#233;galement la construction de rencontres bas&#233;es sur ces personnages, car les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; apparent&#233;s sont regroup&#233;s.&lt;br /&gt;&lt;br /&gt;Nous invitons les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; &#224; adapter les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; pr&#233;sent&#233;s ici &#224; leurs campagnes individuelles. La plupart de ces personnages poss&#232;dent des capacit&#233;s qui correspondent aux arch&#233;types de leur r&#244;le et ont un alignement neutre. L’alignement est bien &#233;videmment facile &#224; modifier et les comp&#233;tences (tout sp&#233;cialement &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt;) peuvent &#234;tre chang&#233;es au vol pour cr&#233;er des personnages aux domaines d’expertise vari&#233;s. La table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Galerie-De-Pnj.html#TABLEPNJ&quot; title=&quot;Galerie de PNJ&quot;&gt;PNJ pr&#234;ts &#224; l&#39;emploi&lt;/a&gt;&quot; ci-dessous reprend tous les arch&#233;types de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; de ce chapitre (et leur(s) niveau(x) de classe et leur regroupement) par ordre de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt;, de sorte que les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; puissent trouver facilement ceux qui leur permettront de cr&#233;er des d&#233;fis adapt&#233;s au niveau des aventuriers. Le caract&#232;re et les motivations personnelles des &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; sont laiss&#233;s &#224; l’appr&#233;ciation du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt;, qui pourra les d&#233;terminer (et modifier les profils) selon les r&#244;les &#224; remplir. &#192; partir des dizaines de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; pr&#233;sent&#233;s ici, il est donc possible de cr&#233;er un nombre de personnages et de rencontres qui n’est limit&#233; que par l’imagination du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Cadeaux des PNJ&lt;a class=&quot;headeranchor&quot; id=&quot;Cadeaux_des_PNJ_1&quot; href=&quot;#Cadeaux_des_PNJ_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;La section &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Cadeaux.html&quot; title=&quot;Les cadeaux des PNJ&quot;&gt;Cadeaux des PNJ&lt;/a&gt;&quot; pr&#233;sente un syst&#232;me optionnel de faveurs, de bonus et avantages mineurs que certains &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; peuvent octroyer aux &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagejoueur.html&quot; title=&quot;PJ&quot;&gt;PJ&lt;/a&gt; avec lesquels ils se lient d’amiti&#233;. Ce syst&#232;me encourage les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagejoueur.html&quot; title=&quot;PJ&quot;&gt;PJ&lt;/a&gt; &#224; s’int&#233;resser davantage aux &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; et permet de r&#233;compenser les personnages autrement qu’avec de l’exp&#233;rience et des tr&#233;sors. Chacun des profils suivant se termine par une suggestion de faveur qui correspond au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; et qui s’inscrit dans ce syst&#232;me de cadeaux. Les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; qui d&#233;sirent utiliser ces faveurs ou cr&#233;er leurs propres avantages peuvent utiliser ces suggestions comme points de d&#233;part pour leurs cr&#233;ations. Cependant, rien ne force les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; &#224; associer &#224; ces &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; les faveurs cit&#233;es, ni m&#234;me aucune autre faveur d’ailleurs. Des explications compl&#232;tes au sujet des faveurs et de la mani&#232;re dont les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagejoueur.html&quot; title=&quot;PJ&quot;&gt;PJ&lt;/a&gt; pourraient en b&#233;n&#233;ficier se trouvent dans la section &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Cadeaux.html&quot; title=&quot;Les cadeaux des PNJ&quot;&gt;Cadeaux des PNJ&lt;/a&gt;&quot;.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Liste des PNJ&lt;a class=&quot;headeranchor&quot; id=&quot;Liste_des_PNJ_2&quot; href=&quot;#Liste_des_PNJ_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TABLEPNJ&quot; href=&quot;#TABLEPNJ&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;script type=&quot;text/javascript&quot;&gt;
addEvent(window, &quot;load&quot;, sortables_init);

var SORT_COLUMN_INDEX;

function sortables_init() {
    // Find all tables with class sortable and make them sortable
    if (!document.getElementsByTagName) return;
    tbls = document.getElementsByTagName(&quot;table&quot;);
    for (ti=0;ti&lt;tbls.length;ti++) {
        thisTbl = tbls[ti];
        if (((&#39; &#39;+thisTbl.className+&#39; &#39;).indexOf(&quot;sortable&quot;) != -1) &amp;&amp; (thisTbl.id)) {

            //initTable(thisTbl.id);
            ts_makeSortable(thisTbl);
        }
    }
}

function ts_makeSortable(table) {
    if (table.rows &amp;&amp; table.rows.length &gt; 0) {
        var firstRow = table.rows[0];
    }
    if (!firstRow) return;

    // We have a first row: assume it&#39;s the header, and make its contents clickable links
    for (var i=0;i&lt;firstRow.cells.length;i++) {
        var cell = firstRow.cells[i];
        var txt = ts_getInnerText(cell);
        cell.innerHTML = &#39;&lt;a href=&quot;#&quot; class=&quot;sortheader&quot; onclick=&quot;ts_resortTable(this);return false;&quot;&gt;&#39;+txt+&#39;&lt;span class=&quot;sortarrow&quot;&gt;   &lt;/span&gt;&lt;/a&gt;&#39;;
    }
}

function ts_getInnerText(el) {
	if (typeof el == &quot;string&quot;) return el;
	if (typeof el == &quot;undefined&quot;) { return el };
	if (el.innerHTML) return el.innerHTML;	//Not needed but it is faster
	var str = &quot;&quot;;

	var cs = el.childNodes;
	var l = cs.length;
	for (var i = 0; i &lt; l; i++) {
		switch (cs[i].nodeType) {
			case 1: //ELEMENT_NODE
				str += ts_getInnerText(cs[i]);
				break;
			case 3:	//TEXT_NODE
				str += cs[i].nodeValue;
				break;
		}
	}
	return str;
}

function ts_resortTable(lnk) {
    // get the span
    var span;
    for (var ci=0;ci&lt;lnk.childNodes.length;ci++) {
        if (lnk.childNodes[ci].tagName &amp;&amp; lnk.childNodes[ci].tagName.toLowerCase() == &#39;span&#39;) span = lnk.childNodes[ci];
    }
    var spantext = ts_getInnerText(span);
    var td = lnk.parentNode;
    var column = td.cellIndex;
    var table = getParent(td,&#39;TABLE&#39;);

	var startline=1;
	if (document.getElementById(table.id+&#39;_tbody&#39;)) {
		startline = 0;
		table = document.getElementById(table.id+&#39;_tbody&#39;);
	}



    // Work out a type for the column
    if (table.rows.length &lt;= 1) return;
    var itm = ts_getInnerText(table.rows[1].cells[column]);
    sortfn = ts_sort_caseinsensitive;
    if (itm.match(/^\d\d[\/-]\d\d[\/-]\d\d\d\d$/)) sortfn = ts_sort_date;
    if (itm.match(/^\d\d[\/-]\d\d[\/-]\d\d$/)) sortfn = ts_sort_date;
    if (itm.match(/^[&#163;$]/)) sortfn = ts_sort_currency;
    if (itm.match(/^[\d\.]+$/)) sortfn = ts_sort_numeric;
    SORT_COLUMN_INDEX = column;
    var firstRow = new Array();
    var newRows = new Array();
    for (i=0;i&lt;table.rows[0].length;i++) { firstRow[i] = table.rows[0][i]; }
    for (j=startline;j&lt;table.rows.length;j++) { newRows[j-startline] = table.rows[j]; }

    newRows.sort(sortfn);

    if (span.getAttribute(&quot;sortdir&quot;) == &#39;down&#39;) {
        ARROW = &#39;  ?&#39;;
        newRows.reverse();
        span.setAttribute(&#39;sortdir&#39;,&#39;up&#39;);
    } else {
        ARROW = &#39;  ?&#39;;
        span.setAttribute(&#39;sortdir&#39;,&#39;down&#39;);
    }

    // We appendChild rows that already exist to the tbody, so it moves them rather than creating new ones
    // don&#39;t do sortbottom rows
    for (i=0;i&lt;newRows.length;i++) { if (!newRows[i].className || (newRows[i].className &amp;&amp; (newRows[i].className.indexOf(&#39;sortbottom&#39;) == -1))) table.tBodies[0].appendChild(newRows[i]);}
    // do sortbottom rows only
    for (i=0;i&lt;newRows.length;i++) { if (newRows[i].className &amp;&amp; (newRows[i].className.indexOf(&#39;sortbottom&#39;) != -1)) table.tBodies[0].appendChild(newRows[i]);}

    // Delete any other arrows there may be showing
    var allspans = document.getElementsByTagName(&quot;span&quot;);
    for (var ci=0;ci&lt;allspans.length;ci++) {
        if (allspans[ci].className == &#39;sortarrow&#39;) {
            if (getParent(allspans[ci],&quot;table&quot;) == getParent(lnk,&quot;table&quot;)) { // in the same table as us?
                allspans[ci].innerHTML = &#39;   &#39;;
            }
        }
    }

    span.innerHTML = ARROW;
}

function getParent(el, pTagName) {
	if (el == null) return null;
	else if (el.nodeType == 1 &amp;&amp; el.tagName.toLowerCase() == pTagName.toLowerCase())	// Gecko bug, supposed to be uppercase
		return el;
	else
		return getParent(el.parentNode, pTagName);
}
function ts_sort_date(a,b) {
    // y2k notes: two digit years less than 50 are treated as 20XX, greater than 50 are treated as 19XX
    aa = ts_getInnerText(a.cells[SORT_COLUMN_INDEX]);
    bb = ts_getInnerText(b.cells[SORT_COLUMN_INDEX]);
    if (aa.length == 10) {
        dt1 = aa.substr(6,4)+aa.substr(3,2)+aa.substr(0,2);
    } else {
        yr = aa.substr(6,2);
        if (parseInt(yr) &lt; 50) { yr = &#39;20&#39;+yr; } else { yr = &#39;19&#39;+yr; }
        dt1 = yr+aa.substr(3,2)+aa.substr(0,2);
    }
    if (bb.length == 10) {
        dt2 = bb.substr(6,4)+bb.substr(3,2)+bb.substr(0,2);
    } else {
        yr = bb.substr(6,2);
        if (parseInt(yr) &lt; 50) { yr = &#39;20&#39;+yr; } else { yr = &#39;19&#39;+yr; }
        dt2 = yr+bb.substr(3,2)+bb.substr(0,2);
    }
    if (dt1==dt2) return 0;
    if (dt1&lt;dt2) return -1;
    return 1;
}

function ts_sort_currency(a,b) { 
    aa = ts_getInnerText(a.cells[SORT_COLUMN_INDEX]).replace(/[^0-9.]/g,&#39;&#39;);
    bb = ts_getInnerText(b.cells[SORT_COLUMN_INDEX]).replace(/[^0-9.]/g,&#39;&#39;);
    return parseFloat(aa) - parseFloat(bb);
}

function ts_sort_numeric(a,b) { 

    aa = parseFloat(ts_getInnerText(a.cells[SORT_COLUMN_INDEX]));
    if (isNaN(aa)) aa = -1;
    bb = parseFloat(ts_getInnerText(b.cells[SORT_COLUMN_INDEX])); 
    if (isNaN(bb)) bb = -1;
    return aa-bb;
}

function removeAccents(s) {
    var r = s.toLowerCase();
    r = r.replace(new RegExp(/\s/g),&quot;&quot;);
    r = r.replace(new RegExp(/[&#224;&#225;&#226;&#227;&#228;&#229;]/g),&quot;a&quot;);
    r = r.replace(new RegExp(/&#230;/g),&quot;ae&quot;);
    r = r.replace(new RegExp(/&#231;/g),&quot;c&quot;);
    r = r.replace(new RegExp(/[&#232;&#233;&#234;&#235;]/g),&quot;e&quot;);
    r = r.replace(new RegExp(/[&#236;&#237;&#238;&#239;]/g),&quot;i&quot;);
    r = r.replace(new RegExp(/&#241;/g),&quot;n&quot;);                
    r = r.replace(new RegExp(/[&#242;&#243;&#244;&#245;&#246;]/g),&quot;o&quot;);
    r = r.replace(new RegExp(/œ/g),&quot;oe&quot;);
    r = r.replace(new RegExp(/[&#249;&#250;&#251;&#252;]/g),&quot;u&quot;);
    r = r.replace(new RegExp(/[&#253;&#255;]/g),&quot;y&quot;);
    r = r.replace(new RegExp(/\W/g),&quot;&quot;);
    return r;
}
function ts_sort_caseinsensitive(a,b) {
    aa = ts_getInnerText(a.cells[SORT_COLUMN_INDEX]).toLowerCase();
    bb = ts_getInnerText(b.cells[SORT_COLUMN_INDEX]).toLowerCase();
    aa = removeAccents(aa);
    bb = removeAccents(bb);
    if (aa==bb) return 0;
    if (aa&lt;bb) return -1;
    return 1;
}

function ts_sort_default(a,b) {

    aa = ts_getInnerText(a.cells[SORT_COLUMN_INDEX]);
    bb = ts_getInnerText(b.cells[SORT_COLUMN_INDEX]);
    if (aa==bb) return 0;
    if (aa&lt;bb) return -1;
    return 1;
}


function addEvent(elm, evType, fn, useCapture)
// addEvent and removeEvent
// cross-browser event handling for IE5+,  NS6 and Mozilla
// By Scott Andrew
{
  if (elm.addEventListener){
    elm.addEventListener(evType, fn, useCapture);
    return true;
  } else if (elm.attachEvent){
    var r = elm.attachEvent(&quot;on&quot;+evType, fn);
    return r;
  } else {
    alert(&quot;Handler could not be removed&quot;);
  }
}
